CREATE TABLE IF NOT EXISTS transport_providers (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',name TEXT NOT NULL,contact_name TEXT,contact_phone TEXT,licence_reference TEXT,insurance_expiry TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,name));
CREATE TABLE IF NOT EXISTS transport_vehicles (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',provider_id INTEGER,name TEXT NOT NULL,registration TEXT,vehicle_type TEXT NOT NULL DEFAULT 'bus',capacity INTEGER NOT NULL CHECK(capacity>0),accessible_capacity INTEGER NOT NULL DEFAULT 0 CHECK(accessible_capacity>=0),status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','maintenance','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,registration),FOREIGN KEY(provider_id) REFERENCES transport_providers(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS transport_journeys (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,title TEXT NOT NULL,journey_type TEXT NOT NULL DEFAULT 'outbound' CHECK(journey_type IN ('outbound','return','shuttle','other')),origin TEXT NOT NULL,destination TEXT NOT NULL,departs_at TEXT NOT NULL,arrives_at TEXT NOT NULL,vehicle_id INTEGER,driver_name TEXT,driver_contact TEXT,meeting_point TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','requested','approved','confirmed','departed','arrived','cancelled','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(vehicle_id) REFERENCES transport_vehicles(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS transport_passengers (id INTEGER PRIMARY KEY AUTOINCREMENT,journey_id INTEGER NOT NULL,party_type TEXT NOT NULL CHECK(party_type IN ('user','staff','student','guardian','team','external')),party_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'passenger',mobility_notes TEXT,pickup_point TEXT,dropoff_point TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),added_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(journey_id,party_type,party_id,role),FOREIGN KEY(journey_id) REFERENCES transport_journeys(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_transport_vehicle_window ON transport_journeys(app_id,vehicle_id,departs_at,arrives_at,status);CREATE INDEX IF NOT EXISTS idx_transport_subject ON transport_journeys(app_id,subject_component,subject_type,subject_id);CREATE INDEX IF NOT EXISTS idx_transport_passengers ON transport_passengers(journey_id,status);
